::cw::lib::Integer skill_card_fixed_price(::cw::lib::Integer level)
{
    // Py は固定価格を任意精度整数で計算する。ネイティブのカー
    // ド項目は符号付き 64 ビットなので、 中間の乗算を桁あふ
    // れさせず正確に計算し、最終価格が表現できなければ拒否する。
    return (::cw::lib::Decimal(level) * ::cw::lib::Decimal(::cw::lib::Integer{200}) +
            ::cw::lib::Decimal(::cw::lib::Integer{400})).to_integer();
}

::cw::lib::Integer add_clamped(::cw::lib::Integer value,
                               ::cw::lib::Integer delta,
                               ::cw::lib::Integer minimum,
                               ::cw::lib::Integer maximum)
{
    // Python は numwrap の前に任意精度整数で加算する。 CardHeader
    // の元の範囲は維持しつつ、ネイティブの中間値の符号付き桁あふれを避ける。
    if (maximum <= minimum) return minimum;
    if (delta > 0 && value > std::numeric_limits<::cw::lib::Integer>::max() - delta)
        return maximum;
    if (delta < 0 && value < std::numeric_limits<::cw::lib::Integer>::min() - delta)
        return minimum;
    return std::clamp<::cw::lib::Integer>(value + delta, minimum, maximum);
}

bool mounted_or_native_file(const std::filesystem::path& path)
{
    if (::cardwirth::platform::is_mounted_user_path(path)) {
        const auto status = ::cardwirth::platform::stat_mounted_user_path(path);
        return status && status->is_file();
    }
    std::error_code ec;
    return std::filesystem::is_regular_file(path, ec);
}

