std::vector<std::filesystem::path> user_work_files_recursive(
    const std::filesystem::path& root)
{
    if (!mounted_or_native_directory(root)) return {};
    if (::cardwirth::platform::is_mounted_user_path(root)) {
        std::vector<std::filesystem::path> files;
        std::vector<std::filesystem::path> pending{root};
        while (!pending.empty()) {
            auto directory = std::move(pending.back());
            pending.pop_back();
            const auto entries = ::cardwirth::platform::list_mounted_user_path(directory);
            if (!entries) continue;
            for (const auto& entry : *entries) {
                if (entry.stat.is_directory()) pending.push_back(entry.path);
                else if (entry.stat.is_file()) files.push_back(entry.path);
            }
        }
        return files;
    }
    std::vector<std::filesystem::path> files;
    std::error_code ec;
    for (std::filesystem::recursive_directory_iterator it(root, ec), end;
         !ec && it != end; it.increment(ec))
        if (it->is_regular_file(ec)) files.push_back(it->path());
    return files;
}

bool transfer_within_same_storage(const std::filesystem::path& source,
                                  const std::filesystem::path& destination,
                                  bool move)
{
    const bool source_mounted = ::cardwirth::platform::is_mounted_user_path(source);
    const bool destination_mounted = ::cardwirth::platform::is_mounted_user_path(destination);
    // 従来のカード移動で、暗号化・ネイティブ保存の境界をまたがせない。
    // その書き出し・取り込みは、保守ツールの明示的な操作として行う。
    if (source_mounted != destination_mounted) return false;
    if (source_mounted)
        return move
            ? ::cardwirth::platform::move_mounted_user_path(source, destination, true)
            : ::cardwirth::platform::copy_mounted_user_path(source, destination, true);
    std::error_code ec;
    if (move) std::filesystem::rename(source, destination, ec);
    else std::filesystem::copy_file(source, destination,
        std::filesystem::copy_options::overwrite_existing, ec);
    return !ec;
}

::cw::lib::String scenario_header_material_path(ScenarioHeader& header,
                                                ::cw::lib::String arg_path)
{
    if (arg_path.empty() || ::cw::binary::image::path_is_code(arg_path)) return arg_path;
    arg_path = ::cw::util::normalize_path(std::move(arg_path));
    const auto scenario_root = std::filesystem::u8path(header.get_fpath());
    if (std::filesystem::is_directory(scenario_root)) {
        const auto candidate = scenario_root / std::filesystem::u8path(arg_path);
        std::error_code ec;
        if (std::filesystem::is_regular_file(candidate, ec))
            return ::cw::lib::encoding::path_to_utf8(candidate);
    }
    return ::cw::util::get_materialpathfromskin(arg_path, ::cw::g_M_IMG, true);
}

