std::shared_ptr<::cw::lib::Bitmap> window_scaled_bitmap(const std::shared_ptr<::cw::lib::Bitmap>& source, ::cw::lib::Real logical_scale)
{
    if (!source || logical_scale <= 0.0 || ::cw::g_UP_WIN <= 0.0) return source;
    const auto [sw, sh] = source->size;
    const auto dw = std::max<::cw::lib::Integer>(1, static_cast<::cw::lib::Integer>(std::llround(sw * ::cw::g_UP_WIN / logical_scale)));
    const auto dh = std::max<::cw::lib::Integer>(1, static_cast<::cw::lib::Integer>(std::llround(sh * ::cw::g_UP_WIN / logical_scale)));
    if (dw == sw && dh == sh) return source;
    auto result = std::make_shared<::cw::lib::Bitmap>(); result->size = {dw, dh};
    if (source->rgba.size() >= static_cast<std::size_t>(sw * sh * 4)) {
        result->rgba.resize(static_cast<std::size_t>(dw * dh * 4));
        for (::cw::lib::Integer y = 0; y < dh; ++y) for (::cw::lib::Integer x = 0; x < dw; ++x) {
            const auto sx = std::min(sw - 1, x * sw / dw), sy = std::min(sh - 1, y * sh / dh);
            std::copy_n(source->rgba.begin() + static_cast<std::ptrdiff_t>((sy * sw + sx) * 4), 4, result->rgba.begin() + static_cast<std::ptrdiff_t>((y * dw + x) * 4));
        }
    }
    result->bmpdepthis1 = source->bmpdepthis1;
    result->scr_scale = source->scr_scale;
    result->has_pixel_alpha = source->has_pixel_alpha;
    result->pixel_bits = source->pixel_bits;
    ::cw::imageretouch::set_surface_metadata(result,
        ::cw::imageretouch::get_surface_metadata(source));
    // ファイルの APNG/WebP を拡縮した場合も、ダイアログ
    // へ公開するビットマップにデコーダー登録を引き継ぐ。 引き継が
    // ないと、二倍・四倍表示で最初の静止表示用フレームが静止画像として
    // コピーされ、 後の表示更新で次のフレームを解決できなくなる。
    return ::cw::util::copy_animated_wxbmp_info(source, result);
}

