void collect_property_nodes(const std::shared_ptr<::cw::data::CWPyElement>& node,
                            const ::cw::lib::String& path,
                            std::map<std::optional<::cw::lib::String>, std::map<::cw::lib::String, ::cw::lib::String>>& attrs,
                            std::map<::cw::lib::String, ::cw::lib::String>* properties = nullptr,
                            std::map<::cw::lib::String, std::vector<std::tuple<::cw::lib::String, std::map<::cw::lib::String, ::cw::lib::String>, ::cw::lib::String>>>* third = nullptr)
{
    if (!node) return;
    if (path.empty()) attrs[std::nullopt] = node->m_attributes;
    if (node->m_tag == "Property") attrs["."] = node->m_attributes;
    for (const auto& child : node->m_children) {
        if (!child) continue;
        if (path.empty() || path == "Property") {
            attrs[child->m_tag] = child->m_attributes;
            if (properties && path == "Property" && child->m_children.empty()) (*properties)[child->m_tag] = child->m_text;
            if (third && path == "Property" && !child->m_children.empty()) {
                auto& seq = (*third)[child->m_tag];
                for (const auto& grand : child->m_children) if (grand) seq.emplace_back(grand->m_tag, grand->m_attributes, grand->m_text);
            }
        }
        collect_property_nodes(child, path.empty() ? child->m_tag : path, attrs, properties, third);
    }
}

std::vector<std::shared_ptr<::cw::image::ImageInfo>> image_infos_from_value(const ::cw::lib::Value& value)
{
    std::vector<std::shared_ptr<::cw::image::ImageInfo>> result;
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
    if (!object || !*object) return result;
    const auto sequence = std::dynamic_pointer_cast<::cw::data::VariantSequence>(*object);
    if (!sequence) return result;
    for (const auto& item : sequence->m_values) {
        const auto* path = std::get_if<::cw::lib::String>(&item.storage());
        if (!path || path->empty()) {
            if (const auto* info_object = std::get_if<::cw::lib::ObjectPtr>(&item.storage()); info_object && *info_object) {
                if (const auto info = std::dynamic_pointer_cast<::cw::image::ImageInfo>(*info_object)) result.push_back(info);
            }
            continue;
        }
        auto info = std::make_shared<::cw::image::ImageInfo>();
        info->initialize(*path, 0, std::nullopt, "Default", std::nullopt);
        result.push_back(std::move(info));
    }
    return result;
}

