::cw::lib::String skip_utf8_chars(const ::cw::lib::String& text, std::size_t count)
{
    std::size_t offset = 0;
    while (count > 0 && offset < text.size()) {
        const auto first = static_cast<unsigned char>(text[offset]);
        std::size_t size = 1;
        if ((first & 0x80) == 0) size = 1;
        else if ((first & 0xe0) == 0xc0) size = 2;
        else if ((first & 0xf0) == 0xe0) size = 3;
        else if ((first & 0xf8) == 0xf0) size = 4;
        if (offset + size > text.size()) size = 1;
        offset += size;
        --count;
    }
    return offset >= text.size() ? ::cw::lib::String{} : text.substr(offset);
}

bool is_gene_coupon(const ::cw::lib::String& name)
{
    // 末尾改行の境界も含め、Py の Unicode の \d と $ の規則を共有す
    // る。 その後 Gene::set_str が Py と同様に各文字を検証する。
    static const ::cw::lib::python_re::Pattern pattern("＠Ｇ\\d{10}$");
    return pattern.match(name);
}

