::cw::lib::String CardHeader::get_showstyle()
{
    if (const auto element = as_element(m_carddata)) {
        if (const auto e = element->find("Property/ShowStyle"); e && *e) return (*e)->m_text;
    } else if (!m_fpath.empty()) {
        if (const auto prop = ::cw::data::xml2element(m_fpath, "Property", std::nullopt, std::nullopt, true, std::nullopt)) {
            if (const auto e = prop->find("ShowStyle"); e && *e) return (*e)->m_text;
        }
    }
    return m_type == "BeastCard" ? "Center" : "FrontOfUser";
}

bool CardHeader::get_can_loaded_scaledimage()
{
    if (const auto element = as_element(m_carddata))
        return element->getbool(".", ::cw::lib::Value("scaledimage"), false);
    if (!m_fpath.empty()) {
        do_write(true);
        GetRootAttribute attrs;
        attrs.initialize(m_fpath);
        const auto it = attrs.m_attrs.find("scaledimage");
        return it != attrs.m_attrs.end() && (it->second == "True" || it->second == "true" || it->second == "1");
    }
    return false;
}

void Gene::initialize(std::optional<std::vector<::cw::lib::Integer>> arg_bits, ::cw::lib::Integer arg_count)
{
    if (arg_bits && !arg_bits->empty()) {
        m_bits = std::move(*arg_bits);
    } else {
        m_bits.assign(10, 0);
    }
    m_count = arg_count;
}

::cw::lib::String Gene::get_str()
{
    ::cw::lib::String result;
    for (const auto bit : m_bits) result += std::to_string(bit);
    return result;
}

void Gene::set_str(::cw::lib::String arg_s, ::cw::lib::Integer arg_count)
{
    // Python と同様、どちらの属性へ代入する前にも全文字の int 変換を済
    // ませる。 Unicode の十進数字を解釈し、失敗時は古い状態を維持する。
    const auto utf16 = ::cw::lib::encoding::utf8_to_utf16(arg_s, ::cw::lib::encoding::ByteOrder::Little);
    std::vector<::cw::lib::Integer> bits;
    bits.reserve(utf16.size() / 2);
    for (std::size_t i = 0; i < utf16.size(); i += 2) {
        std::uint32_t ch = static_cast<unsigned char>(utf16[i]) |
            (static_cast<unsigned char>(utf16[i + 1]) << 8);
        if (ch >= 0xd800 && ch <= 0xdbff) {
            const auto low = static_cast<unsigned char>(utf16[i + 2]) |
                (static_cast<unsigned char>(utf16[i + 3]) << 8);
            ch = 0x10000 + ((ch - 0xd800) << 10) + (low - 0xdc00);
            i += 2;
        }
        const auto digit = ::cw::lib::python_decimal_digit(ch);
        if (!digit) {
            throw std::invalid_argument("Gene::set_str: non-decimal character");
        }
        bits.push_back(static_cast<::cw::lib::Integer>(*digit));
    }
    m_bits = std::move(bits);
    m_count = arg_count;
}

void Gene::reverse_bit(::cw::lib::Integer arg_index)
{
    if (0 <= arg_index && arg_index < 10) {
        auto& bit = m_bits.at(static_cast<std::size_t>(arg_index));
        bit = bit ? 0 : 1;
    }
}

void Gene::set_bit(::cw::lib::Integer arg_index, ::cw::lib::Integer arg_value)
{
    if (0 <= arg_index && arg_index < 10) {
        // Py と同様、十ビットの位置を受け付け、渡された vector が短けれ
        // ば IndexError 相当を出す。 要求された変更を黙って捨てない。
        m_bits.at(static_cast<std::size_t>(arg_index)) = arg_value ? 1 : 0;
    }
}

void Gene::set_randombit()
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_dice)
        throw std::logic_error("Gene::set_randombit requires the runtime Dice");
    // Py と同様、共通のゲーム用 Dice から十面の抽選を一回消費
    // する。 遺伝子が短い場合は選択位置で例外とし、先に拡張しない。
    const auto roll = ::cw::g_cwpy->m_dice->roll(1, 10);
    m_bits.at(static_cast<std::size_t>(roll - 1)) = 1;
}

void Gene::set_talentbit(::cw::lib::String arg_talent, ::cw::lib::String arg_oldtalent)
{
    for (const auto& nature : ::cw::setting::Setting::s_natures) if (nature && "＿" + nature->m_name == arg_talent) {
        for (std::size_t index = 0; index < nature->m_genepattern.size(); ++index)
            if (nature->m_genepattern[index] == '1') m_bits.at(index) = 1;
        if (nature->m_genecount == 0 && !arg_oldtalent.empty()) set_talentbit(arg_oldtalent);
        break;
    }
}

::cw::lib::Integer Gene::count_bits()
{
    return static_cast<::cw::lib::Integer>(std::count_if(m_bits.begin(), m_bits.end(), [](::cw::lib::Integer bit) {
        return bit != 0;
    }));
}

std::shared_ptr<::cw::header::Gene> Gene::reverse()
{
    std::vector<::cw::lib::Integer> bits;
    bits.reserve(m_bits.size());
    for (const auto bit : m_bits) bits.push_back(bit ? 0 : 1);
    auto result = std::make_shared<Gene>();
    result->initialize(std::move(bits), 0);
    return result;
}

std::shared_ptr<::cw::header::Gene> Gene::fusion(std::shared_ptr<::cw::header::Gene> arg_gene)
{
    std::vector<::cw::lib::Integer> bits;
    if (arg_gene) {
        const auto size = std::min(m_bits.size(), arg_gene->m_bits.size());
        bits.reserve(size);
        for (std::size_t i = 0; i < size; ++i) bits.push_back(m_bits[i] ^ arg_gene->m_bits[i]);
    }
    auto result = std::make_shared<Gene>();
    result->initialize(std::move(bits), 0);
    return result;
}

std::shared_ptr<::cw::header::Gene> Gene::rotate_father()
{
    auto bits = m_bits;
    if (!bits.empty()) {
        // Py のスライスと同様、範囲を vector の長さに収める。 短い vector
        // を超える回数では元の順序になり、その長さで剰余を取った回転にはしない。
        const auto offset = static_cast<std::size_t>(((m_count % 10 + 10) % 10 + 9) % 10);
        const auto count = std::min(offset, bits.size());
        std::rotate(bits.begin(), bits.begin() + count, bits.end());
    }
    auto result = std::make_shared<Gene>();
    result->initialize(std::move(bits), 0);
    return result;
}

std::shared_ptr<::cw::header::Gene> Gene::rotate_mother()
{
    auto bits = m_bits;
    if (!bits.empty()) {
        const auto father_offset = ((m_count % 10 + 10) % 10 + 9) % 10;
        const auto count = std::min(static_cast<std::size_t>((10 - father_offset) % 10), bits.size());
        std::rotate(bits.begin(), bits.begin() + count, bits.end());
    }
    auto result = std::make_shared<Gene>();
    result->initialize(std::move(bits), 0);
    return result;
}

namespace {
void synchronize_header_input(const ::cw::lib::String& arg_fpath)
{
    if (!arg_fpath.empty() && ::cw::g_fsync && ::cw::g_fsync->is_waiting(arg_fpath))
        ::cw::g_fsync->sync();
}

template<class Reader>
void parse_header_xml(Reader& reader, const ::cw::lib::String& arg_fpath, std::optional<::cw::lib::Value> arg_stream = std::nullopt)
{
    std::unique_ptr<std::remove_pointer_t<XML_Parser>, decltype(&XML_ParserFree)>
        parser(XML_ParserCreate(nullptr), &XML_ParserFree);
    if (!parser) throw std::bad_alloc();
    struct ReaderState { Reader* reader; XML_Parser parser; } state{&reader, parser.get()};
    XML_SetUserData(parser.get(), &state);
    XML_SetElementHandler(parser.get(),
        [](void* owner, const XML_Char* name, const XML_Char** values) noexcept {
            auto& state = *static_cast<ReaderState*>(owner);
            try {
                std::map<::cw::lib::String, ::cw::lib::String> attrs;
                for (; *values; values += 2) attrs.emplace(values[0], values[1]);
                state.reader->start_element(name, std::move(attrs));
            } catch (...) { XML_StopParser(state.parser, XML_FALSE); }
        },
        [](void* owner, const XML_Char* name) noexcept {
            auto& state = *static_cast<ReaderState*>(owner);
            try {
                if constexpr (requires(Reader& reader) { reader.end_element(::cw::lib::String{}); })
                    state.reader->end_element(name);
            }
            catch (...) { XML_StopParser(state.parser, XML_FALSE); }
        });
    XML_SetCharacterDataHandler(parser.get(),
        [](void* owner, const XML_Char* text, int length) noexcept {
            auto& state = *static_cast<ReaderState*>(owner);
            try {
                if constexpr (requires(Reader& reader) { reader.character_data(::cw::lib::String{}); })
                    state.reader->character_data(::cw::lib::String(text, static_cast<std::size_t>(length)));
            }
            catch (...) { XML_StopParser(state.parser, XML_FALSE); }
        });
    // C++ の Value ストリームは Python のファイルオブジェクトではなく、取得済みの
    // UTF-8・バイト列を持つ。 どちらも上限付きの断片で同じ Expat コールバックへ渡す。
    if (arg_stream) {
        ::cw::lib::String memory;
        if (const auto* text = std::get_if<::cw::lib::String>(&arg_stream->storage())) memory = *text;
        else if (const auto* bytes = std::get_if<::cw::lib::Bytes>(&arg_stream->storage()))
            memory.assign(reinterpret_cast<const char*>(bytes->data()), bytes->size());
        else throw std::invalid_argument("Unsupported XML stream carrier");
        try {
            for (std::size_t pos = 0;;) {
                const auto length = std::min<std::size_t>(2048, memory.size() - pos);
                if (XML_Parse(parser.get(), memory.data() + pos, static_cast<int>(length), length == 0)
                    != XML_STATUS_OK || !length) break;
                pos += length;
            }
        } catch (...) { /* Python の ParseFile と同様、途中までのデータを保持する。 */ }
        return;
    }
    const auto path = ::cw::lib::encoding::path_from_utf8(arg_fpath);
    const bool mounted = ::cardwirth::platform::is_mounted_user_path(path);
    // ネイティブのストリームにはディレクトリーを開けて読み取り時に失敗するものがあるが、
    // Python は例外を抑止する解析・読み取り範囲の外の open で拒否する。
    if (mounted_or_native_directory(path))
        throw std::runtime_error("Cannot open XML directory: " + arg_fpath);
    auto input = mounted ? ::cardwirth::platform::open_mounted_user_file(path) : nullptr;
    std::ifstream native;
    if (!mounted) native.open(path, std::ios::binary);
    // Python と同様、ファイルは解析用の try/except の外で開き、欠落・読み取り不能を失敗として伝える。
    if ((mounted && !input) || (!mounted && !native.is_open()))
        throw std::runtime_error("Cannot open XML: " + arg_fpath);
    // ParseFile は上限付きの断片で読み、対象・Property の終了で止まる。
    // マウント済みストレージでも、生の読み取り処理だけを変えて解析方針は共有する。 Python
    // と同様、ParseFile 内のコールバック・XML・読み取り失敗は抑止し、蓄
    // 積した文字・属性・階層を保持する。open と fsync の失敗は抑止しない。
    std::array<char, 2048> buffer;
    try {
        for (;;) {
            std::size_t size;
            if (mounted) {
                size = input->read(std::as_writable_bytes(std::span(buffer)));
                if (!size && !input->good()) break;
            } else {
                native.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
                size = static_cast<std::size_t>(native.gcount());
                if (!size && native.bad()) break;
            }
            if (XML_Parse(parser.get(), buffer.data(), static_cast<int>(size), size == 0)
                != XML_STATUS_OK || !size) break;
        }
    } catch (...) { /* Python の ParseFile の例外境界と同様、途中までのデータを保持する。 */ }
}
}

void GetName::initialize(::cw::lib::String arg_fpath, ::cw::lib::String arg_tagname)
{
    synchronize_header_input(arg_fpath);
    m_name.clear(); m_stack.clear(); m_attrs.clear(); m_tagname = arg_tagname;
    parse_header_xml(*this, arg_fpath);
}

void GetName::start_element(::cw::lib::String arg_name, std::map<::cw::lib::String, ::cw::lib::String> arg_attrs)
{
    if (m_stack.empty()) m_attrs[std::nullopt] = arg_attrs;
    m_stack.push_back(arg_name);
    if (m_stack.size() == 2 && arg_name == "Property") m_attrs["."] = arg_attrs;
    if (m_stack.size() == 3 && m_stack[1] == "Property") m_attrs[arg_name] = arg_attrs;
}

void GetName::end_element(::cw::lib::String arg_name)
{
    const auto tag = value_string(m_tagname);
    if (m_stack.size() >= 2 && m_stack[1] == "Property" &&
        (m_stack.size() == 2 || (m_stack.size() == 3 && m_stack[2] == tag)))
        // Py と同様、取り出す前に例外を出し、停止したパーサーの階層を維持する。
        throw std::runtime_error("GetName target complete");
    if (!m_stack.empty()) m_stack.pop_back(); (void)arg_name;
}

void GetName::character_data(::cw::lib::String arg_data)
{
    const auto tag = value_string(m_tagname);
    if (m_stack.size() == 3 && m_stack[1] == "Property" && m_stack[2] == tag) m_name += arg_data;
}

void GetProperty::initialize(::cw::lib::String arg_fpath, std::optional<::cw::lib::Value> arg_stream, std::optional<::cw::lib::Value> arg_tag)
{
    synchronize_header_input(arg_fpath);
    m_attrs.clear(); m_properties.clear(); m_stack.clear(); m_third.clear(); m_tag.clear();
    if (arg_tag) {
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_tag->storage()); object && *object) {
            if (auto sequence = std::dynamic_pointer_cast<::cw::data::VariantSequence>(*object)) m_tag = sequence->m_values;
            else m_tag.push_back(*arg_tag);
        } else m_tag.push_back(*arg_tag);
    }
    parse_header_xml(*this, arg_fpath, std::move(arg_stream));
}

void GetProperty::start_element(::cw::lib::String arg_name, std::map<::cw::lib::String, ::cw::lib::String> arg_attrs)
{
    if (m_stack.empty()) m_attrs[std::nullopt] = arg_attrs;
    m_stack.push_back(arg_name);
    if (m_stack.size() == 2 && arg_name == "Property") m_attrs["."] = arg_attrs;
    if (m_stack.size() == 3 && m_stack[1] == "Property") m_attrs[arg_name] = arg_attrs;
    if (m_stack.size() == 4 && m_stack[1] == "Property") m_third[m_stack[2]].emplace_back(arg_name, arg_attrs, "");
}

void GetProperty::end_element(::cw::lib::String arg_name)
{
    if (m_stack.size() >= 2 && m_stack[1] == "Property" &&
        (m_stack.size() == 2 || (m_stack.size() == 3 && std::any_of(m_tag.begin(), m_tag.end(), [&](const auto& tag) {
            const auto* text = std::get_if<::cw::lib::String>(&tag.storage());
            return text && *text == m_stack[2];
        }))))
        // Python と同様、Property・選択タグの終了では、階層から取り出す前に例外を出す。
        throw std::runtime_error("GetProperty target complete");
    if (!m_stack.empty()) m_stack.pop_back(); (void)arg_name;
}

void GetProperty::character_data(::cw::lib::String arg_data)
{
    if (m_stack.size() > 2 && m_stack[1] == "Property") m_properties.try_emplace(m_stack[2], "");
    if (m_stack.size() == 3 && m_stack[1] == "Property") m_properties[m_stack[2]] += arg_data;
    if (m_stack.size() == 4 && m_stack[1] == "Property" && !m_third[m_stack[2]].empty()) std::get<2>(m_third[m_stack[2]].back()) += arg_data;
}

void GetRootAttribute::initialize(::cw::lib::String arg_fpath)
{
    m_attrs.clear();
    synchronize_header_input(arg_fpath);
    // Py と同様、ルートの開始イベントで止める。 後の本文が不正でも、読み取
    // り済みの属性を無効にしたり、完全な XML ツリーを要求したりしない。
    parse_header_xml(*this, arg_fpath);
}

void GetRootAttribute::start_element(::cw::lib::String arg_name, std::map<::cw::lib::String, ::cw::lib::String> arg_attrs)
{
    m_attrs = std::move(arg_attrs); (void)arg_name;
    // 共通 Expat コールバックの境界でこの完了通知を捕捉し、 Python
    // が例外で最初の要素で ParseFile を止める動作に合わせる。
    throw std::runtime_error("GetRootAttribute root complete");
}

void InfoCardHeader::initialize(std::shared_ptr<::cw::data::CWPyElement> arg_data, bool arg_can_loaded_scaledimage)
{
    m_id = 0; m_name.clear(); m_desc.clear(); m_author = ""; m_scenario = ""; m_imgpaths = {}; m__cardimg.reset(); m__cardscale = -1.0; m__wxcardscale = -1.0; m__skindirname = {};
    m_can_loaded_scaledimage = arg_can_loaded_scaledimage; m_anotherscenariocard = false; m_negaflag = false; m_clickedflag = false; m_deal_per = 100;
    if (!arg_data) return;
    m_id = arg_data->getint("Id", std::nullopt, 0); m_name = arg_data->gettext("Name", ""); m_desc = arg_data->gettext("Description", "");
    m_scenario = arg_data->gettext("Scenario", ""); m_author = arg_data->gettext("Author", "");
    if (::cw::g_cwpy) if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_sdata.storage()); object && *object) if (const auto scenario = std::dynamic_pointer_cast<::cw::data::ScenarioData>(*object)) { m_scenario = scenario->m_name; m_author = scenario->m_author; }
    const auto infos = ::cw::image::get_imageinfos(arg_data, false);
    auto sequence = std::make_shared<::cw::data::VariantSequence>();
    for (const auto& info : infos) if (info) sequence->m_values.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
    m_imgpaths = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(sequence));
    set_cardimg(arg_can_loaded_scaledimage, false);
}

void InfoCardHeader::set_cardimg(bool arg_can_loaded_scaledimage, bool arg_anotherscenariocard)
{
    m_can_loaded_scaledimage = arg_can_loaded_scaledimage; m_anotherscenariocard = arg_anotherscenariocard;
    auto image = std::make_shared<::cw::image::CardImage>();
    image->initialize(image_infos_from_value(m_imgpaths), "INFO", m_name, "", arg_can_loaded_scaledimage,
                      true, "", arg_anotherscenariocard, {0, 0});
    m__cardimg = std::move(image);
    m__cardscale = ::cw::g_UP_SCR; m__wxcardscale = ::cw::g_UP_WIN;
    m__skindirname = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::lib::Value(::cw::g_cwpy->m_setting->m_skindirname) : ::cw::lib::Value{};
    m__bordering_cardname = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::lib::Value(::cw::g_cwpy->m_setting->get_bordering_cardname()) : ::cw::lib::Value{};
}

std::shared_ptr<::cw::image::CardImage> InfoCardHeader::get_cardimg()
{
    const auto scaled = value_real(m__cardscale, -1.0) != ::cw::g_UP_SCR || value_real(m__wxcardscale, -1.0) != ::cw::g_UP_WIN;
    const auto setting = ::cw::g_cwpy ? ::cw::g_cwpy->m_setting : nullptr;
    const auto skindir_changed = setting && value_string(m__skindirname) != setting->m_skindirname;
    const auto bordering = setting && value_bool(m__bordering_cardname, false) != setting->get_bordering_cardname();
    if (!m__cardimg || scaled || skindir_changed || bordering)
        set_cardimg(value_bool(m_can_loaded_scaledimage), value_bool(m_anotherscenariocard));
    return m__cardimg;
}

std::shared_ptr<::cw::lib::Bitmap> InfoCardHeader::get_cardwxbmp(std::optional<std::shared_ptr<::cw::sprite::card::PlayerCard>> arg_test_aptitude)
{
    // Py と同様、この互換引数は受け付けるが、情報カードには適性・
    // 状態の重ね合わせを描かない。 通常のビットマップ経路を使う。
    (void)arg_test_aptitude;
    if (!get_cardimg()) return {};
    return m_negaflag ? m__cardimg->get_wxnegabmp() : m__cardimg->get_wxbmp();
}

std::shared_ptr<::cw::lib::Surface> InfoCardHeader::get_cardimg_2()
{
    if (!get_cardimg()) return {};
    if (!m__cardimg) return {};
    return m_negaflag ? m__cardimg->get_negaimg() : m__cardimg->get_image();
}

void PartyHeader::initialize(std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_data, std::optional<::cw::lib::Value> arg_dbrec)
{
    // Py と同様、XML・データベースのどちらの分岐より前にも order を初期化する。 再初期
    // 化時も含め、add_party/new_order が数値の -1 を参照できるようにする。
    m_order = -1;
    m_data.reset();
    m_fpath = {}; m_name.clear(); m_money = 0; m_members = {};
    m__membernames.reset(); m__memberdescs.reset(); m__membercoupons.reset(); m__memberlevels.reset(); m__memberprops.reset();
    if (arg_dbrec) if (const auto record = record_from_value(*arg_dbrec)) {
        m_fpath = ::cw::util::normalize_path(value_string(record_field(record, "fpath"))); m_name = value_string(record_field(record, "name")); m_money = value_integer(record_field(record, "money"));
        const auto members = value_string(record_field(record, "members"));
        for (const auto& member : split_newlines_like_python(members)) m_members.emplace_back(member);
        return;
    }
    if (!arg_data || !*arg_data) return;
    const auto data = *arg_data;
    // Party XML は Name/Money を Property
    // の子要素として保存する。 属性として読むと、XML からデ
    // ータベースキャッシュを再構築した際にパーティー名が空になる。
    m_fpath = ::cw::util::normalize_path(data->m_fpath); m_name = data->gettext("Name", ""); m_money = data->getint("Money", std::nullopt, 0);
    const auto members = data->find("Members");
    if (members && *members) for (const auto& member : (*members)->m_children) if (member && !member->m_text.empty()) m_members.emplace_back(member->m_text);
}

bool PartyHeader::is_adventuring()
{
    const auto* path = std::get_if<::cw::lib::String>(&m_fpath.storage());
    if (!path || path->empty()) return false;
    auto wsl = std::filesystem::u8path(*path); wsl.replace_extension(".wsl");
    const auto wsl_utf8 = ::cw::lib::encoding::path_to_utf8(wsl);
    // ディレクトリー形式の WSL でも、ZIP 形式と同じ削除・Temp の規則を使う。
    return !::cw::util::get_yadofilepath(wsl_utf8, true).empty();
}

std::optional<std::shared_ptr<::cw::header::ScenarioHeader>> PartyHeader::get_sceheader()
{
    if (::cw::g_fsync) ::cw::g_fsync->sync();
    const auto* fpath = std::get_if<::cw::lib::String>(&m_fpath.storage());
    if (!fpath || fpath->empty()) return std::nullopt;
    auto wsl = std::filesystem::u8path(*fpath); wsl.replace_extension(".wsl");
    auto wsl_utf8 = ::cw::lib::encoding::path_to_utf8(wsl);
    auto resolved = ::cw::util::get_yadofilepath(wsl_utf8, true);
    if (resolved.empty()) return std::nullopt;
    const auto path = read_scenario_path(resolved);
    if (path.empty()) return std::nullopt;
    if (::cw::g_cwpy) {
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_frame.storage()); object && *object) {
            if (const auto frame = std::dynamic_pointer_cast<::cw::frame::Frame>(*object)) {
                const auto db = frame->open_scenariodb();
                if (db && *db) return (*db)->search_path(path, {});
            }
        }
    }
    return std::nullopt;
}

::cw::lib::String PartyHeader::read_scenario_path(const ::cw::lib::String& resolved_log)
{
    const auto wsl = std::filesystem::u8path(resolved_log);
    std::shared_ptr<::cw::data::CWPyElement> property;
    // resolved_log はネイティブのファイルシステムではなく、マウント済みストレージに属す
    // る場合がある。 get_yadofilepath やアーカイブ読み取りと同じ論理ビューを使う。
    if (::cw::util::path_is_directory(resolved_log)) {
        const auto log = wsl / "ScenarioLog.xml";
        if (!::cw::util::path_is_file(::cw::lib::encoding::path_to_utf8(log))) return {};
        property = ::cw::data::xml2element(::cw::lib::encoding::path_to_utf8(log), "Property", std::nullopt, std::nullopt, true, std::nullopt);
    } else if (::cw::util::path_is_file(resolved_log)) {
        // WSLはZIP互換アーカイブ。utilの共通アーカイブリーダーで
        // ScenarioLog.xml/Propertyを読み、展開せずにシナリオDB検索へ渡す。
        property = ::cw::util::get_elementfromzip(resolved_log, "ScenarioLog.xml", "Property");
    } else {
        return {};
    }
    return property ? property->gettext("WsnPath", "") : ::cw::lib::String{};
}

std::vector<::cw::lib::String> PartyHeader::get_memberpaths(std::optional<::cw::lib::String> arg_yadodir)
{
    // Python の header.py と同様、Windows が名前を変えたか判
    // 断する前に待機する。 元の表記で存在確認する前に、予約済み書き込みを完了する。
    if (::cw::g_fsync) ::cw::g_fsync->sync();
    std::vector<::cw::lib::String> result;
    const bool explicit_yadodir = arg_yadodir && !arg_yadodir->empty();
    const auto base = explicit_yadodir ? std::filesystem::u8path(*arg_yadodir) : std::filesystem::path{};
    for (const auto& member : m_members) if (const auto* name = std::get_if<::cw::lib::String>(&member.storage())) {
        auto path = explicit_yadodir ? base / "Adventurer" /
            ::cw::lib::encoding::path_from_utf8(*name + ".xml") :
            std::filesystem::u8path(::cw::util::join_yadodir("Adventurer/" + *name + ".xml"));
        if (!mounted_or_native_file(path)) {
            const auto trimmed = ::cw::binary::util::strip_python_spaces(*name);
            path = explicit_yadodir ? base / "Adventurer" /
                ::cw::lib::encoding::path_from_utf8(trimmed + ".xml") :
                std::filesystem::u8path(::cw::util::join_yadodir("Adventurer/" + trimmed + ".xml"));
        }
        result.push_back(::cw::lib::encoding::path_to_utf8(path));
    }
    return result;
}

std::vector<std::shared_ptr<::cw::header::GetProperty>> PartyHeader::_get_properties()
{
    if (!m__memberprops) {
        // Py と同様、読み取り前にキャッシュを公開する。 メンバー読み取り
        // に失敗しても、成功した先頭部分を後の取得処理で使えるようにする。
        m__memberprops.emplace();
        for (const auto& path : get_memberpaths(std::nullopt)) {
            auto prop = std::make_shared<GetProperty>();
            prop->initialize(path, std::nullopt, std::nullopt);
            m__memberprops->push_back(std::move(prop));
        }
    }
    return *m__memberprops;
}

std::vector<::cw::lib::String> PartyHeader::get_membernames()
{
    if (!m__membernames) {
        // C++ の公開取得 API は値のコピーを返すが、保持キャッシュは Python と同様
        // に一つの Property スナップショットを共有する。 途中までの取得結果も含める。
        m__membernames.emplace();
        for (const auto& prop : _get_properties()) {
            if (!prop) throw std::logic_error("Null party property");
            const auto value = prop->m_properties.find("Name");
            m__membernames->push_back(value == prop->m_properties.end() ? "" : value->second);
        }
    }
    return *m__membernames;
}

std::vector<::cw::lib::String> PartyHeader::get_memberdescs()
{
    if (!m__memberdescs) {
        // C++ の公開取得 API は値のコピーを返すが、保持キャッシュは Python と同様
        // に一つの Property スナップショットを共有する。 途中までの取得結果も含める。
        m__memberdescs.emplace();
        for (const auto& prop : _get_properties()) {
            if (!prop) throw std::logic_error("Null party property");
            const auto value = prop->m_properties.find("Description");
            m__memberdescs->push_back(value == prop->m_properties.end() ? "" : value->second);
        }
    }
    return *m__memberdescs;
}

std::vector<std::vector<::cw::lib::String>> PartyHeader::get_membercoupons()
{
    if (m__membercoupons) return *m__membercoupons;
    std::vector<std::vector<::cw::lib::String>> result;
    for (const auto& prop : _get_properties()) { std::vector<::cw::lib::String> coupons; const auto it = prop->m_third.find("Coupons"); if (it != prop->m_third.end()) for (auto coupon = it->second.rbegin(); coupon != it->second.rend(); ++coupon) if (!std::get<2>(*coupon).empty()) coupons.push_back(std::get<2>(*coupon)); result.push_back(std::move(coupons)); }
    m__membercoupons = result; return result;
}

std::vector<::cw::lib::Integer> PartyHeader::get_memberlevels()
{
    if (!m__memberlevels) {
        m__memberlevels.emplace();
        for (const auto& prop : _get_properties()) {
            if (!prop) throw std::logic_error("Null party property");
            const auto value = prop->m_properties.find("Level");
            // Py と同様、XML の getint の int(float) ではなく int(str) を使う
            // 。 公開のネイティブ vector は int64 なので、範囲外の Python 整数は拒否する。
            m__memberlevels->push_back(::cw::lib::require_python_integer(
                value == prop->m_properties.end() ? "1" : value->second));
        }
    }
    return *m__memberlevels;
}

::cw::lib::Real PartyHeader::get_average_level()
{
    const auto levels = get_memberlevels(); if (levels.empty()) return 1.0; return static_cast<::cw::lib::Real>(std::accumulate(levels.begin(), levels.end(), ::cw::lib::Integer{0})) / static_cast<::cw::lib::Real>(levels.size());
}

::cw::lib::Integer PartyHeader::get_highest_level()
{
    const auto levels = get_memberlevels();
    if (levels.empty()) throw std::invalid_argument("max() arg is an empty sequence");
    return *std::max_element(levels.begin(), levels.end());
}

void PartyRecordHeader::initialize(std::optional<::cw::lib::String> arg_fpath, std::optional<::cw::lib::Value> arg_dbrec, std::optional<std::shared_ptr<::cw::thread::StoredParty>> arg_partyrecord)
{
    m_fpath = {}; m_name.clear(); m_money = 0; m_members.clear(); m_membernames.clear(); m_backpack = {}; m_backpack_names.clear();
    if (arg_dbrec) if (const auto record = record_from_value(*arg_dbrec)) {
        m_fpath = ::cw::util::normalize_path(value_string(record_field(record, "fpath"))); m_name = value_string(record_field(record, "name")); m_money = value_integer(record_field(record, "money"));
        for (const auto& item : split_newlines_like_python(value_string(record_field(record, "members")))) m_members.emplace_back(item);
        for (const auto& item : split_newlines_like_python(value_string(record_field(record, "membernames")))) m_membernames.emplace_back(item);
        m_backpack_names = split_newlines_like_python(value_string(record_field(record, "backpack")));
        if (m_membernames.size() < m_members.size()) m_membernames.resize(m_members.size(), ::cw::lib::Value(""));
        return;
    }
    if (arg_fpath && !arg_fpath->empty() && !(arg_partyrecord && *arg_partyrecord)) {
        const auto fpath = ::cw::util::normalize_path(*arg_fpath);
        m_fpath = fpath; const auto tree = ::cw::data::xml2etree(fpath, "", std::nullopt, std::nullopt, false);
        if (tree) { m_name = tree->gettext("Property/Name", ""); m_money = tree->getint("Property/Money", std::nullopt, 0); if (const auto members = tree->find("Property/Members")) if (*members) for (const auto& member : (*members)->m_children) if (member) { m_members.emplace_back(member->m_text); m_membernames.emplace_back(member->get("name", "")); } if (const auto backpack = tree->find("BackpackRecord")) if (*backpack) for (const auto& card : (*backpack)->m_children) if (card) m_backpack_names.push_back(card->get("name", "")); }
    } else if (arg_partyrecord && *arg_partyrecord) {
        const auto& record = **arg_partyrecord; m_fpath = ::cw::util::normalize_path(record.m_fpath); if (const auto* value = std::get_if<::cw::lib::String>(&record.m_name.storage())) m_name = *value; m_money = value_integer(record.m_money, 0);
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&record.m_members.storage()); object && *object) if (const auto members = std::dynamic_pointer_cast<::cw::data::VariantSequence>(*object)) {
            for (const auto& member : members->m_values) {
                if (const auto* member_object = std::get_if<::cw::lib::ObjectPtr>(&member.storage()); member_object && *member_object) {
                    if (const auto tree = std::dynamic_pointer_cast<::cw::data::CWPyElementTree>(*member_object)) {
                        const auto path = tree->m_fpath;
                        const auto stem = ::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(path).stem());
                        m_members.emplace_back(stem);
                        m_membernames.emplace_back(tree->gettext("Property/Name", ""));
                    } else if (const auto element = std::dynamic_pointer_cast<::cw::data::CWPyElement>(*member_object)) {
                        const auto path = element->m_fpath;
                        m_members.emplace_back(::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(path).stem()));
                        m_membernames.emplace_back(element->gettext("Property/Name", ""));
                    } else m_members.push_back(member);
                } else m_members.push_back(member);
            }
        }
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&record.m_backpack.storage()); object && *object) if (const auto backpack = std::dynamic_pointer_cast<::cw::data::VariantSequence>(*object)) for (const auto& item : backpack->m_values) if (const auto header = std::dynamic_pointer_cast<::cw::header::CardHeader>(std::get<::cw::lib::ObjectPtr>(item.storage()))) m_backpack_names.push_back(header->m_name);
        // StoredParty の項目には通常は名前がある。古い項目で欠けて
        // いれば空欄を残し、 メンバー ID を XML パスと扱わず、get_membernames()
        // が現在の宿から解決できるようにする。
        if (m_membernames.size() < m_members.size()) m_membernames.resize(m_members.size(), ::cw::lib::Value(""));
    }
}

void PartyRecordHeader::rename_member(::cw::lib::String arg_fpath, ::cw::lib::String arg_name)
{
    const auto stem = ::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(arg_fpath).stem()); std::size_t index = m_members.size();
    for (std::size_t i = 0; i < m_members.size(); ++i) if (const auto* value = std::get_if<::cw::lib::String>(&m_members[i].storage()); value && *value == stem) { index = i; break; }
    if (index == m_members.size()) return;
    if (index >= m_membernames.size()) m_membernames.resize(index + 1); m_membernames[index] = arg_name;
    const auto* fpath = std::get_if<::cw::lib::String>(&m_fpath.storage()); if (!fpath) return; auto tree = ::cw::data::xml2etree(*fpath, "", std::nullopt, std::nullopt, false); if (tree) { tree->edit("Property/Members/Member[" + std::to_string(index + 1) + "]", arg_name, "name"); tree->write_xml(true); }
}

void PartyRecordHeader::vanish_member(::cw::lib::String arg_fpath)
{
    // 元の不具合を修正する。Python は旧形式の欠落名を解決しても空の
    // 属性を書き込むが、 ここでは解決した名前を XML に保持し、メンバ
    // ーファイルが削除された後も記録の再読み込みで識別できるようにする。
    const auto stem = ::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(arg_fpath).stem()); std::size_t index = m_members.size();
    for (std::size_t i = 0; i < m_members.size(); ++i) if (const auto* value = std::get_if<::cw::lib::String>(&m_members[i].storage()); value && *value == stem) { index = i; break; }
    if (index == m_members.size()) return;
    m_members[index] = ::cw::lib::Value("");
    if (index < m_membernames.size()) { const auto* oldname = std::get_if<::cw::lib::String>(&m_membernames[index].storage()); if (!oldname || oldname->empty()) { auto name = GetName{}; name.initialize(arg_fpath, "Name"); m_membernames[index] = name.m_name; } }
    const auto* fpath = std::get_if<::cw::lib::String>(&m_fpath.storage()); if (!fpath) return; auto tree = ::cw::data::xml2etree(*fpath, "", std::nullopt, std::nullopt, false); if (tree) { const auto path = "Property/Members/Member[" + std::to_string(index + 1) + "]"; tree->edit(path, "", std::nullopt); const auto* name = index < m_membernames.size() ? std::get_if<::cw::lib::String>(&m_membernames[index].storage()) : nullptr; if (tree->getattr(path, "name", "").empty() && name) tree->edit(path, *name, std::optional<::cw::lib::String>("name")); tree->write_xml(true); }
}

std::vector<::cw::lib::String> PartyRecordHeader::get_memberpaths()
{
    if (::cw::g_fsync) ::cw::g_fsync->sync();
    std::vector<::cw::lib::String> result;
    result.reserve(m_members.size());
    for (const auto& member : m_members) {
        const auto* name = std::get_if<::cw::lib::String>(&member.storage());
        if (!name || name->empty()) { result.emplace_back(); continue; }
        auto relative = ::cw::util::join_paths(
            {::cw::lib::Value("Adventurer"), ::cw::lib::Value(*name + ".xml")});
        auto path = ::cw::util::join_yadodir(relative);
        if (!::cw::util::path_is_file(path)) {
            // Python と同様、元の表記が存在しない場合だけ、Windows
            // 向けに正規化した旧ファイル名を再試行する。
            relative = ::cw::util::join_paths(
                {::cw::lib::Value("Adventurer"),
                 ::cw::lib::Value(::cw::lib::python_strip(*name) + ".xml")});
            path = ::cw::util::join_yadodir(relative);
        }
        result.push_back(std::move(path));
    }
    return result;
}

std::vector<::cw::lib::String> PartyRecordHeader::get_membernames()
{
    std::vector<::cw::lib::String> result; const auto paths = get_memberpaths();
    for (std::size_t i = 0; i < paths.size(); ++i) { const auto* stored = i < m_membernames.size() ? std::get_if<::cw::lib::String>(&m_membernames[i].storage()) : nullptr; if (stored && !stored->empty()) result.push_back(*stored); else if (!paths[i].empty() && ::cw::util::path_is_file(paths[i])) { GetName name; name.initialize(paths[i], "Name"); result.push_back(name.m_name); } else result.push_back("<Vanished>"); }
    return result;
}

void RaceHeader::initialize(std::shared_ptr<::cw::data::CWPyElement> arg_data)
{
    m_name.clear(); m_desc.clear(); m_coupons.clear(); m_coupon_entries.clear(); m_coeff_level.reset(); m_coeff_ep.reset();
    m_automaton = m_constructure = m_undead = m_unholy = false; m_noeffect_weapon = m_noeffect_magic = false; m_resist_fire = m_resist_ice = false; m_weakness_fire = m_weakness_ice = false;
    m_dex = m_agl = m_py_int = m_str = m_vit = m_min = 6; m_aggressive = m_cheerful = m_brave = m_cautious = m_trickish = 0.0; m_avoid = m_resist = m_defense = 0;
    if (!arg_data) return;
    m_name = arg_data->gettext("Name", ""); m_desc = arg_data->gettext("Description", "");
    m_automaton = arg_data->getbool("Feature/Type", ::cw::lib::Value("automaton"), false); m_constructure = arg_data->getbool("Feature/Type", ::cw::lib::Value("constructure"), false); m_undead = arg_data->getbool("Feature/Type", ::cw::lib::Value("undead"), false); m_unholy = arg_data->getbool("Feature/Type", ::cw::lib::Value("unholy"), false);
    m_noeffect_weapon = arg_data->getbool("Feature/NoEffect", ::cw::lib::Value("weapon"), false); m_noeffect_magic = arg_data->getbool("Feature/NoEffect", ::cw::lib::Value("magic"), false);
    m_resist_fire = arg_data->getbool("Feature/Resist", ::cw::lib::Value("fire"), false); m_resist_ice = arg_data->getbool("Feature/Resist", ::cw::lib::Value("ice"), false); m_weakness_fire = arg_data->getbool("Feature/Weakness", ::cw::lib::Value("fire"), false); m_weakness_ice = arg_data->getbool("Feature/Weakness", ::cw::lib::Value("ice"), false);
    m_dex = arg_data->getint("Ability/Physical", ::cw::lib::Value("dex"), 6); m_agl = arg_data->getint("Ability/Physical", ::cw::lib::Value("agl"), 6); m_py_int = arg_data->getint("Ability/Physical", ::cw::lib::Value("int"), 6); m_str = arg_data->getint("Ability/Physical", ::cw::lib::Value("str"), 6); m_vit = arg_data->getint("Ability/Physical", ::cw::lib::Value("vit"), 6); m_min = arg_data->getint("Ability/Physical", ::cw::lib::Value("min"), 6);
    m_aggressive = arg_data->getfloat("Ability/Mental", ::cw::lib::Value("aggressive"), 0.0); m_cheerful = arg_data->getfloat("Ability/Mental", ::cw::lib::Value("cheerful"), 0.0); m_brave = arg_data->getfloat("Ability/Mental", ::cw::lib::Value("brave"), 0.0); m_cautious = arg_data->getfloat("Ability/Mental", ::cw::lib::Value("cautious"), 0.0); m_trickish = arg_data->getfloat("Ability/Mental", ::cw::lib::Value("trickish"), 0.0);
    m_avoid = arg_data->getint("Ability/Enhance", ::cw::lib::Value("avoid"), 0); m_resist = arg_data->getint("Ability/Enhance", ::cw::lib::Value("resist"), 0); m_defense = arg_data->getint("Ability/Enhance", ::cw::lib::Value("defense"), 0);
    if (const auto coefficient = arg_data->find("Coefficient")) { if ((*coefficient)->m_attributes.contains("level")) m_coeff_level = arg_data->getfloat("Coefficient", ::cw::lib::Value("level"), 1.0); if ((*coefficient)->m_attributes.contains("ep")) m_coeff_ep = arg_data->getint("Coefficient", ::cw::lib::Value("ep"), 10); }
    if (const auto coupons = arg_data->find("Coupons")) if (*coupons) for (const auto& coupon : (*coupons)->m_children) if (coupon) { const auto name = coupon->m_text; const auto value = coupon->getint(".", ::cw::lib::Value("value"), 0); m_coupons.emplace_back(name); m_coupon_entries.emplace_back(name, value); }
}

void SavedJPDCImageHeader::initialize(std::optional<::cw::lib::String> arg_fpath, std::optional<::cw::lib::Value> arg_dbrec)
{
    m_dpath = ::cw::lib::Value{}; m_fpath = ::cw::lib::Value{};
    m_fpaths.clear(); m_fpaths_typed.clear(); m_scenarioname.clear(); m_scenarioauthor.clear();
    if (arg_dbrec) if (const auto record = record_from_value(*arg_dbrec)) {
        m_fpath = value_string(record_field(record, "fpath")); m_scenarioname = value_string(record_field(record, "scenarioname")); m_scenarioauthor = value_string(record_field(record, "scenarioauthor")); m_dpath = value_string(record_field(record, "dpath"));
        const auto paths = value_string(record_field(record, "fpaths"));
        for (const auto& path : split_newlines_like_python(paths)) {
            m_fpaths.emplace_back(::cw::lib::Value(path));
            m_fpaths_typed.emplace_back(path);
        }
        return;
    } else if (const auto* path = std::get_if<::cw::lib::String>(&arg_dbrec->storage())) arg_fpath = *path;
    if (!arg_fpath || arg_fpath->empty()) return;
    m_fpath = ::cw::lib::Value(*arg_fpath);
    const auto tree = ::cw::data::xml2etree(*arg_fpath, "", std::nullopt, std::nullopt, false);
    if (!tree) return;
    m_scenarioname = tree->gettext("Property/ScenarioName", "");
    m_scenarioauthor = tree->gettext("Property/ScenarioAuthor", "");
    m_dpath = ::cw::lib::Value(tree->getattr("Materials", "dpath", ""));
    const auto materials = tree->find("Materials");
    if (materials && *materials && !value_string(m_dpath).empty()) {
        for (const auto& child : (*materials)->m_children) {
            if (!child || child->m_text.empty()) continue;
            m_fpaths_typed.push_back(child->m_text);
            m_fpaths.emplace_back(::cw::lib::Value(child->m_text));
        }
    }
}

std::shared_ptr<::cw::header::SavedJPDCImageHeader> SavedJPDCImageHeader::create_header(std::optional<std::shared_ptr<::cw::debug::logging::DebugLog>> arg_debuglog)
{
    auto header = std::make_shared<SavedJPDCImageHeader>();
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata) return header;
    auto ydata = *::cw::g_cwpy->m_ydata;
    ydata->changed();
    if (::cw::g_fsync) ::cw::g_fsync->sync();
    auto sdata = [&]() -> std::shared_ptr<::cw::data::ScenarioData> {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_sdata.storage());
        return object && *object ? std::dynamic_pointer_cast<::cw::data::ScenarioData>(*object) : nullptr;
    }();
    if (!sdata) return header;

    const auto value_string = [](const ::cw::lib::Value& value) {
        if (const auto* text = std::get_if<::cw::lib::String>(&value.storage())) return *text;
        return ::cw::lib::String{};
    };
    const auto scenarioname = value_string(sdata->m_name);
    const auto scenarioauthor = value_string(sdata->m_author);
    const auto key = std::make_tuple(scenarioname, scenarioauthor);
    auto existing = ydata->m_savedjpdcimage.find(key);
    if (existing != ydata->m_savedjpdcimage.end() && existing->second) {
        // Python版は既存ヘッダの相対dpathを維持したまま旧素材を除去する。
        header = existing->second;
        header->remove_all();
    } else {
        header->m_scenarioname = scenarioname;
        header->m_scenarioauthor = scenarioauthor;
    }
    header->m_fpaths.clear();
    header->m_fpaths_typed.clear();
    const auto base = std::filesystem::u8path(::cw::g_cwpy->m_tempdir) / "SavedJPDCImage";
    if (value_string(header->m_dpath).empty()) {
        auto dname = ::cw::util::repl_dischar(scenarioname);
        if (dname.empty()) dname = "Scenario";
        // 一時保存先だけでなく保存済みの宿も含め、 別作者の同名シナ
        // リオが公開済みのディレクトリーを再利用しないようにする。
        const auto unique = ::cw::util::dupcheck_plus(
            ::cw::lib::encoding::path_to_utf8(base / std::filesystem::u8path(dname)), true, false);
        header->m_dpath = ::cw::lib::encoding::path_to_utf8(
            std::filesystem::u8path(unique).lexically_relative(base));
    }
    const auto dpath = value_string(header->m_dpath);
    auto destination = base / std::filesystem::u8path(dpath);
    const auto source = std::filesystem::u8path(value_string(::cw::g_tempdir)) /
                        "ScenarioLog" / "TempFile";
    if (mounted_or_native_directory(source)) {
        for (const auto& file : user_work_files_recursive(source)) {
            const auto relative = file.lexically_relative(source);
            const auto target = destination / "Materials" / relative;
            if (!mounted_or_native_mkdir(target.parent_path()) ||
                !transfer_within_same_storage(file, target, false))
                throw std::runtime_error("JPDC image copy failed: " + ::cw::lib::encoding::path_to_utf8(target));
            {
                const auto relpath = ::cw::lib::encoding::path_to_utf8(relative);
                header->m_fpaths_typed.push_back(relpath);
                if (ydata->m_deletedpaths) ydata->m_deletedpaths->discard(::cw::lib::encoding::path_to_utf8(target));
                if (arg_debuglog && *arg_debuglog) (*arg_debuglog)->add_jpdcimage(relpath);
            }
        }
    }
    for (const auto& path : header->m_fpaths_typed) header->m_fpaths.emplace_back(::cw::lib::Value(path));
    if (header->m_fpaths_typed.empty()) {
        ydata->m_savedjpdcimage.erase(key);
        return header;
    }
    auto root = ::cw::data::make_element("SavedJPDCImage");
    auto property = ::cw::data::make_element("Property");
    property->append(::cw::data::make_element("ScenarioName", scenarioname));
    property->append(::cw::data::make_element("ScenarioAuthor", scenarioauthor));
    root->append(property);
    auto materials = ::cw::data::make_element("Materials", "", std::map<::cw::lib::String, ::cw::lib::String>{{"dpath", dpath}});
    for (const auto& path : header->m_fpaths_typed) materials->append(::cw::data::make_element("Material", path));
    root->append(materials);
    const auto fpath = ::cw::lib::encoding::path_to_utf8(destination / "SavedJPDCImage.xml");
    auto tree = std::make_shared<::cw::data::CWPyElementTree>(root, fpath); tree->write_file(fpath);
    if (ydata->m_deletedpaths) ydata->m_deletedpaths->discard(fpath);
    header->m_fpath = ::cw::lib::Value(fpath);
    ydata->m_savedjpdcimage[key] = header;
    return header;
}

void SavedJPDCImageHeader::remove_all()
{
    const auto* dpath = std::get_if<::cw::lib::String>(&m_dpath.storage());
    // 不正データへの保護として、空のシナリオディレクトリーを拒否する
    // 。 そのまま扱うと全シナリオの保存素材の削除を予約してしまう。
    if (!dpath || dpath->empty() || !::cw::g_cwpy) return;
    if (::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata) (*::cw::g_cwpy->m_ydata)->changed();
    if (::cw::g_fsync) ::cw::g_fsync->sync();
    std::vector<std::filesystem::path> roots;
    if (::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata) roots.push_back(std::filesystem::u8path((*::cw::g_cwpy->m_ydata)->m_yadodir) / "SavedJPDCImage" / *dpath);
    roots.push_back(std::filesystem::u8path(::cw::g_cwpy->m_tempdir) / "SavedJPDCImage" / *dpath);
    for (const auto& root : roots) {
        if (mounted_or_native_directory(root) && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata && (*::cw::g_cwpy->m_ydata)->m_deletedpaths) {
            for (const auto& file : user_work_files_recursive(root))
                (*::cw::g_cwpy->m_ydata)->m_deletedpaths->add(::cw::lib::encoding::path_to_utf8(file));
        }
    }
}

void ScenarioHeader::initialize(::cw::lib::Value arg_dbrec, std::optional<std::vector<std::map<::cw::lib::String, ::cw::lib::Value>>> arg_imgdbrec)
{
    m_dbrec_fields.clear(); m_imgdbrec_typed = arg_imgdbrec.value_or(std::vector<std::map<::cw::lib::String, ::cw::lib::Value>>{});
    m_dpath.clear(); m_fname.clear(); m_images.clear(); m_imgpaths.clear();
    m_images[1] = {};
    m__wxbmps.reset(); m__wxbmps_noscale.reset(); m__imginfos.reset(); m_skindir.reset(); m__up_win.reset(); m__up_scr.reset();

    // 生成されたValueはスカラーまたはElementを保持できる。ElementをDB行互換
    // として受け取った場合は、SQLite列名と同じ属性／子要素を抽出する。
    const auto dbrecord = record_from_value(arg_dbrec);
    if (dbrecord) {
        // DbRecordはsqlite3.Rowの全列を保持する薄いアダプタであり、
        // NULL/bytesもValueのまま残して、後段の画像選択へ渡す。
        for (const auto& [key, value] : dbrecord->fields) m_dbrec_fields.emplace(key, value);
        m_dpath = value_string(record_field(dbrecord, "dpath"));
        m_fname = value_string(record_field(dbrecord, "fname"));
        m_type = value_integer(record_field(dbrecord, "type"));
        m_name = value_string(record_field(dbrecord, "name"));
        m_author = value_string(record_field(dbrecord, "author"));
        m_desc = value_string(record_field(dbrecord, "desc"));
        m_skintype = value_string(record_field(dbrecord, "skintype"));
        m_levelmin = value_integer(record_field(dbrecord, "levelmin"));
        m_levelmax = value_integer(record_field(dbrecord, "levelmax"));
        m_coupons = value_string(record_field(dbrecord, "coupons"));
        m_couponsnum = value_integer(record_field(dbrecord, "couponsnum"));
        m_startid = value_integer(record_field(dbrecord, "startid"));
        m_tags = value_string(record_field(dbrecord, "tags"));
        m_ctime = numeric_value(record_field(dbrecord, "ctime"));
        m_mtime = numeric_value(record_field(dbrecord, "mtime"));
        m_wsnversion = value_string(record_field(dbrecord, "wsnversion"));
        const auto main_path = value_string(record_field(dbrecord, "imgpath"));
        const auto main_image = optional_bytes(record_field(dbrecord, "image"));
        if (main_image || !main_path.empty()) {
            m_images[1].push_back(main_image);
            auto info = std::make_shared<::cw::image::ImageInfo>();
            info->initialize(main_path, 0, std::nullopt, value_string(record_field(dbrecord, "postype"), "Default"), std::nullopt);
            m_imgpaths.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
        }
        // 画像DB行はscale/numorderを尊重し、行順に依存せず空スロットも維持。
        ::cw::lib::Integer maxorder = -1;
        for (const auto& row_record : m_imgdbrec_typed) maxorder = std::max(maxorder, value_integer(row_record.contains("numorder") ? row_record.at("numorder") : ::cw::lib::Value{}));
        for (const auto& row_record : m_imgdbrec_typed) {
            const auto scale = value_integer(row_record.contains("scale") ? row_record.at("scale") : ::cw::lib::Value{}, 1);
            const auto order = value_integer(row_record.contains("numorder") ? row_record.at("numorder") : ::cw::lib::Value{}, 0);
            if (order < 0) continue;
            if (maxorder == std::numeric_limits<::cw::lib::Integer>::max()) throw std::overflow_error("ScenarioHeader image order exceeds container range");
            const auto required_size = static_cast<std::size_t>(maxorder) + 1;
            const auto order_index = static_cast<std::size_t>(order);
            auto& images = m_images[scale];
            if (required_size > images.size()) images.resize(required_size);
            images[order_index] = optional_bytes(row_record.contains("image") ? row_record.at("image") : ::cw::lib::Value{});
            auto info = std::make_shared<::cw::image::ImageInfo>();
            info->initialize(value_string(row_record.contains("imgpath") ? row_record.at("imgpath") : ::cw::lib::Value{}), 0, std::nullopt,
                             value_string(row_record.contains("postype") ? row_record.at("postype") : ::cw::lib::Value{}, "Default"), std::nullopt);
            m_imgpaths.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(info)));
        }
        return;
    }
    std::shared_ptr<::cw::data::CWPyElement> row;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_dbrec.storage()); object && *object)
        row = std::dynamic_pointer_cast<::cw::data::CWPyElement>(*object);
    auto field = [&](const ::cw::lib::String& key) -> ::cw::lib::Value {
        if (!row) return {};
        auto value = row->get(key, "");
        if (!value.empty()) return ::cw::lib::Value(value);
        const auto child = row->find(key);
        if (child && *child) return ::cw::lib::Value((*child)->get_text());
        return {};
    };
    for (const auto& key : {"dpath", "type", "fname", "name", "author", "desc", "skintype", "levelmin", "levelmax", "coupons", "couponsnum", "startid", "tags", "ctime", "mtime", "wsnversion", "imgpath"}) {
        auto value = field(key); if (!std::holds_alternative<std::monostate>(value.storage())) m_dbrec_fields.emplace(key, value);
    }
    auto string_field = [&](const char* key) { const auto it = m_dbrec_fields.find(key); if (it == m_dbrec_fields.end()) return ::cw::lib::String{}; if (const auto* v = std::get_if<::cw::lib::String>(&it->second.storage())) return *v; return ::cw::lib::String{}; };
    auto int_field = [&](const char* key) { const auto it = m_dbrec_fields.find(key); return it == m_dbrec_fields.end() ? ::cw::lib::Integer{} : value_integer(it->second, 0); };
    auto numeric_field = [&](const char* key) { const auto it = m_dbrec_fields.find(key); return it == m_dbrec_fields.end() ? ::cw::lib::Value(::cw::lib::Integer{0}) : numeric_value(it->second); };
    m_dpath = string_field("dpath"); m_fname = string_field("fname"); m_type = ::cw::lib::Value(int_field("type")); m_name = string_field("name"); m_author = string_field("author"); m_desc = string_field("desc"); m_skintype = string_field("skintype");
    m_levelmin = int_field("levelmin"); m_levelmax = int_field("levelmax"); m_coupons = string_field("coupons"); m_couponsnum = int_field("couponsnum"); m_startid = int_field("startid"); m_tags = string_field("tags"); m_ctime = numeric_field("ctime"); m_mtime = numeric_field("mtime"); m_wsnversion = string_field("wsnversion");
    if (!m_dpath.empty() || !m_fname.empty()) {
        const auto path = string_field("imgpath");
        const auto image = field("image");
        if (!std::holds_alternative<std::monostate>(image.storage()) || !path.empty()) m_images[1].push_back(optional_bytes(image));
        if (!path.empty()) m_imgpaths.emplace_back(::cw::lib::Value(path));
    }
}

::cw::lib::Value ScenarioHeader::get_mtime_reversed()
{
    if (const auto* value = std::get_if<::cw::lib::Integer>(&m_mtime.storage())) {
        if (*value == (std::numeric_limits<::cw::lib::Integer>::min)())
            return ::cw::lib::Value(::cw::lib::Decimal::parse(std::to_string(*value).substr(1)));
        return ::cw::lib::Value(-*value);
    }
    // ネイティブの並べ替えは厳密な弱順序を必要とするため、NaN を数
    // 値キーの対象外とする。 Python の正負の無限大は維持する。
    if (const auto* value = std::get_if<::cw::lib::Real>(&m_mtime.storage()))
        return std::isnan(*value) ? ::cw::lib::Value{} : ::cw::lib::Value(-*value);
    if (const auto* value = std::get_if<::cw::lib::Decimal>(&m_mtime.storage())) {
        auto text = value->to_string(true);
        if (!text.empty() && text.front() == '-') text.erase(text.begin()); else text.insert(text.begin(), '-');
        return ::cw::lib::Value(::cw::lib::Decimal::parse(text));
    }
    return ::cw::lib::Value{};
}

::cw::lib::String ScenarioHeader::get_fpath()
{
    return m_dpath + "/" + m_fname;
}

void ScenarioHeader::set_fpath(::cw::lib::String arg_fpath)
{
    const auto path = std::filesystem::u8path(::cw::util::normalize_path(std::move(arg_fpath)));
    m_dpath = ::cw::lib::encoding::path_to_utf8(path.parent_path());
    m_fname = ::cw::lib::encoding::path_to_utf8(path.filename());
}

std::tuple<std::vector<std::shared_ptr<::cw::lib::Bitmap>>, std::vector<std::shared_ptr<::cw::lib::Bitmap>>, std::vector<std::shared_ptr<::cw::image::ImageInfo>>> ScenarioHeader::get_wxbmps(bool arg_mask)
{
    const auto up_win = ::cw::g_UP_WIN;
    const auto up_scr = ::cw::g_UP_SCR;
    ::cw::lib::String skin;
    if (::cw::g_cwpy) skin = value_string(::cw::g_cwpy->m_skindir);
    if (!m__wxbmps || !m__wxbmps_noscale || !m__imginfos || !m_skindir || *m_skindir != skin || !m__up_win || *m__up_win != up_win || !m__up_scr || *m__up_scr != up_scr) {
        m_skindir = skin; m__up_win = up_win; m__up_scr = up_scr;
        m__wxbmps = std::vector<std::shared_ptr<::cw::lib::Bitmap>>{};
        m__wxbmps_noscale = std::vector<std::shared_ptr<::cw::lib::Bitmap>>{};
        m__imginfos = std::vector<std::shared_ptr<::cw::image::ImageInfo>>{};
        auto& scaled = *m__wxbmps; auto& noscale = *m__wxbmps_noscale; auto& infos = *m__imginfos;
        const auto scale_s = image_scale_from_real(up_scr);
        const auto& base_images = m_images.at(1);
        const auto image_count = std::min(base_images.size(), m_imgpaths.size());
        for (std::size_t i = 0; i < image_count; ++i) {
            std::shared_ptr<::cw::image::ImageInfo> info;
            if (i < m_imgpaths.size()) {
                if (const auto* path = std::get_if<::cw::lib::String>(&m_imgpaths[i].storage())) { info = std::make_shared<::cw::image::ImageInfo>(); info->initialize(*path, 0, std::nullopt, "Default", std::nullopt); }
                else if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_imgpaths[i].storage()); object && *object) info = std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object);
            }
            const std::optional<::cw::lib::Bytes> base = base_images[i];
            std::optional<::cw::lib::Bytes> selected;
            ::cw::lib::Integer selected_scale = 1;
            for (auto scale = scale_s; scale >= 1; scale /= 2) {
                const auto it = m_images.find(scale);
                // Py と同様、最初に利用可能な倍率キーで止める。 そ
                // の項目が None・空でも、低い解像度へ戻らない。
                if (it != m_images.end()) { selected = it->second.at(i); selected_scale = scale; break; }
            }
            if (selected && selected->empty()) selected.reset();
            if (!selected && (!info || info->m_path.empty())) continue;
            std::shared_ptr<::cw::lib::Bitmap> bmp_noscale, bmp;
            if (selected) {
                bmp_noscale = bitmap_from_bytes(base, arg_mask);
                // load_wxbmp() が検出した透過色を保持する。 has_colorkey=false
                // で上書きすると、1 ビットのシナリオ画像が張り
                // 紙・ログで不透明な矩形として表示されてしまう。
                auto noscale_metadata = ::cw::imageretouch::get_surface_metadata(bmp_noscale);
                // wx.Bitmap は Depth1Surface のラッパーではない。 load_wxbmp()
                // が渡す、実際に 1 ビットの入力である印だけを保持する。
                noscale_metadata.logical_scale = 1.0;
                bmp_noscale->scr_scale = 1.0;
                ::cw::imageretouch::set_surface_metadata(bmp_noscale, noscale_metadata);
                auto selected_bitmap = selected_scale == 1 ? bmp_noscale : bitmap_from_bytes(selected, arg_mask);
                auto selected_metadata = ::cw::imageretouch::get_surface_metadata(selected_bitmap);
                selected_metadata.logical_scale = static_cast<::cw::lib::Real>(selected_scale);
                // ネイティブの logical_scale は共通合成処理用の入力ピクセル
                // 倍率を持つ。 Py ではその倍率を scr_scale として公開する。
                selected_bitmap->scr_scale = static_cast<::cw::lib::Real>(selected_scale);
                ::cw::imageretouch::set_surface_metadata(selected_bitmap, selected_metadata);
                bmp = window_scaled_bitmap(selected_bitmap, static_cast<::cw::lib::Real>(selected_scale));
            } else {
                const auto path = scenario_header_material_path(*this, info->m_path);
                if (path.empty()) continue;
                bmp_noscale = ::cw::util::load_wxbmp(path, arg_mask, nullptr, {}, std::nullopt, true, false, true, std::nullopt);
                auto selected_bitmap = up_scr == 1.0 ? bmp_noscale : ::cw::util::load_wxbmp(path, arg_mask, nullptr, {}, std::nullopt, true, true, false, ::cw::lib::Value(up_scr));
                const auto metadata = ::cw::imageretouch::get_surface_metadata(selected_bitmap);
                bmp = window_scaled_bitmap(selected_bitmap, metadata.logical_scale);
            }
            noscale.push_back(std::move(bmp_noscale)); scaled.push_back(std::move(bmp)); infos.push_back(info ? info : std::make_shared<::cw::image::ImageInfo>());
        }
    }
    return {*m__wxbmps, *m__wxbmps_noscale, *m__imginfos};
}

std::optional<std::tuple<std::vector<std::shared_ptr<::cw::lib::Surface>>, std::vector<std::shared_ptr<::cw::image::ImageInfo>>>> ScenarioHeader::get_bmps(bool arg_mask, std::optional<::cw::lib::Real> arg_up_scr)
{
    const auto up_scr = arg_up_scr.value_or(::cw::g_UP_SCR);
    const auto scale_s = image_scale_from_real(up_scr);
    const bool stored_scale = std::any_of(m_images.begin(), m_images.end(),
        [up_scr](const auto& entry) { return static_cast<::cw::lib::Real>(entry.first) == up_scr; });
    if (up_scr != 1.0 && (m_imgpaths.empty() || !stored_scale)) {
        bool has_path = false;
        // このネイティブの公開引数は Real である。 要求倍率の付随ファイル名を確認する際
        // 、末尾の .0 も含め Python の str(float) と同じ表記を使う。
        const auto scale_text = ::cw::lib::python_float_repr(up_scr);
        for (const auto& value : m_imgpaths) {
            ::cw::lib::String rawpath = value_string(value);
            if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage()); object && *object) if (const auto info = std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object)) rawpath = info->m_path;
            const auto path = scenario_header_material_path(*this, rawpath); if (path.empty()) continue;
            const auto p = std::filesystem::u8path(path);
            const auto scaled_name = ::cw::lib::encoding::path_to_utf8(p.stem()) + ".x" +
                                     scale_text + ::cw::lib::encoding::path_to_utf8(p.extension());
            const auto scaled_path = p.parent_path() / std::filesystem::u8path(scaled_name);
            if (::cw::util::path_is_file(::cw::lib::encoding::path_to_utf8(scaled_path))) { has_path = true; break; }
        }
        if (!has_path) return std::nullopt;
    }
    std::vector<std::shared_ptr<::cw::lib::Surface>> surfaces;
    std::vector<std::shared_ptr<::cw::image::ImageInfo>> infos;
    const auto& base_images = m_images.at(1);
    const auto image_count = std::min(base_images.size(), m_imgpaths.size());
    for (std::size_t i = 0; i < image_count; ++i) {
        std::shared_ptr<::cw::image::ImageInfo> info;
        if (i < m_imgpaths.size()) {
            if (const auto* path = std::get_if<::cw::lib::String>(&m_imgpaths[i].storage())) { info = std::make_shared<::cw::image::ImageInfo>(); info->initialize(*path, 0, std::nullopt, "Default", std::nullopt); }
            else if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_imgpaths[i].storage()); object && *object) info = std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object);
        }
        std::optional<::cw::lib::Bytes> selected; ::cw::lib::Integer selected_scale = 1;
        for (auto scale = scale_s; scale >= 1; scale /= 2) { const auto it = m_images.find(scale); if (it != m_images.end()) { selected = it->second.at(i); selected_scale = scale; break; } }
        if (selected && selected->empty()) selected.reset();
        if (!selected && (!info || info->m_path.empty())) continue;
        std::shared_ptr<::cw::lib::Surface> surface;
        if (selected) {
            surface = surface_from_bytes(selected, arg_mask);
            auto metadata=::cw::imageretouch::get_surface_metadata(surface);
            metadata.depth1=true;metadata.logical_scale=static_cast<::cw::lib::Real>(selected_scale);
            ::cw::imageretouch::set_surface_metadata(surface, metadata);
        } else {
            const auto path = scenario_header_material_path(*this, info->m_path); if (path.empty()) continue;
            surface = ::cw::util::load_image(path, arg_mask, {0, 0}, std::nullopt, true, false, true, false, ::cw::lib::Value(scale_s), false);
        }
        surfaces.push_back(std::move(surface)); infos.push_back(info ? info : std::make_shared<::cw::image::ImageInfo>());
    }
    return std::make_tuple(std::move(surfaces), std::move(infos));
}

void UnknownRaceHeader::initialize(std::shared_ptr<::cw::setting::Setting> arg_setting)
{
    m_name = ""; m_desc = ""; m_automaton = false; m_constructure = false; m_undead = false; m_unholy = false; m_noeffect_weapon = false; m_noeffect_magic = false; m_resist_fire = false; m_resist_ice = false; m_weakness_fire = false; m_weakness_ice = false; m_dex = m_agl = m_py_int = m_str = m_vit = m_min = 6; m_aggressive = m_cheerful = m_brave = m_cautious = m_trickish = 0; m_avoid = m_resist = m_defense = 0; m_coupons.clear(); m_coeff_level.reset(); m_coeff_ep.reset();
    if (arg_setting && arg_setting->m_msgs) {
        m_name = arg_setting->m_msgs->get("unknown_race_name", "");
        m_desc = arg_setting->m_msgs->get("unknown_race_description", "");
    }
}

::cw::lib::Value g_sqlite3_Row{};

std::vector<std::shared_ptr<::cw::image::ImageInfo>> to_imgpaths(::cw::lib::Value arg_dbrec, std::optional<std::shared_ptr<::cw::lib::SqlCursor>> arg_imgdbrec)
{
    std::vector<std::shared_ptr<::cw::image::ImageInfo>> result;
    const auto record = record_from_value(arg_dbrec);
    if (record) {
        const auto path = value_string(record_field(record, "imgpath"));
        const auto postype = value_string(record_field(record, "postype"), "Default");
        if (!path.empty()) { auto info = std::make_shared<::cw::image::ImageInfo>(); info->initialize(path, 0, std::nullopt, postype.empty() ? "Default" : postype, std::nullopt); result.push_back(info); }
    }
    if (arg_imgdbrec && *arg_imgdbrec) {
        // SqlCursorは列名を持たないcompat形式だが、DB検索SQLの列順
        // (imgpath, postype)を明記して全行を読み出す。
        for (const auto& row : (*arg_imgdbrec)->rows) {
            if (row.columns.empty()) continue;
            const auto* path = std::get_if<::cw::lib::String>(&row.columns[0].storage());
            const auto* postype = row.columns.size() > 1 ? std::get_if<::cw::lib::String>(&row.columns[1].storage()) : nullptr;
            if (!path) continue;
            auto info = std::make_shared<::cw::image::ImageInfo>(); info->initialize(*path, 0, std::nullopt, postype && !postype->empty() ? *postype : "Default", std::nullopt); result.push_back(std::move(info));
        }
    }
    return result;
}

::cw::lib::Integer cardtype_to_pocket(::cw::lib::String arg_ctype)
{
    if (arg_ctype == "SkillCard") return ::cw::g_POCKET_SKILL;
    if (arg_ctype == "ItemCard") return ::cw::g_POCKET_ITEM;
    if (arg_ctype == "BeastCard") return ::cw::g_POCKET_BEAST;
    throw std::invalid_argument("cardtype_to_pocket: unknown card type " + arg_ctype);
}

::cw::lib::String CardHeader_write_create_newpath(std::optional<std::shared_ptr<::cw::data::Party>> arg_party, ::cw::lib::String arg_cardtype, ::cw::lib::String arg_name)
{
    ::cw::lib::String base;
    if (arg_party && *arg_party) base = ::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(value_string((*arg_party)->m_path)).parent_path());
    if (base.empty() && ::cw::g_cwpy) base = ::cw::g_cwpy->m_yadodir;
    if (base.empty()) throw std::runtime_error("CardHeader_write_create_newpath: yado directory is unavailable");
    if (arg_cardtype.empty()) throw std::invalid_argument("CardHeader_write_create_newpath: empty card type");
    const auto path = std::filesystem::u8path(base) / std::filesystem::u8path(arg_cardtype) /
                      std::filesystem::u8path(::cw::util::repl_dischar(arg_name) + ".xml");
    if (!mounted_or_native_mkdir(path.parent_path()))
        throw std::runtime_error("create card directory failed: " +
            ::cw::lib::encoding::path_to_utf8(path.parent_path()));
    return ::cw::util::dupcheck_plus(::cw::lib::encoding::path_to_utf8(path), false, false);
}

bool is_removewithstatus(std::shared_ptr<::cw::data::CWPyElement> arg_carddata, ::cw::lib::Value arg_target)
{
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_target.storage());
    const auto target = object && *object ? std::dynamic_pointer_cast<::cw::character::Character>(*object) : nullptr;
    if (!target || !arg_carddata) return false;
    const auto condition = arg_carddata->find("Property/RemovalCondition");
    if (!condition || !*condition) return target->is_unconscious();
    for (const auto& status : (*condition)->m_children) {
        if (status && status->m_tag == "Status" && status->m_text == "Unconscious" && target->is_unconscious()) return true;
    }
    return false;
}

::cw::lib::String enforce_str(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::String>(&arg_value.storage())) return *value;
    throw std::invalid_argument("enforce_str: value is not a string");
}

std::optional<::cw::lib::String> enforce_optional_str(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::String>(&arg_value.storage())) return *value;
    if (arg_value.is_none()) return std::nullopt;
    throw std::invalid_argument("enforce_optional_str: value is neither string nor None");
}

::cw::lib::Integer enforce_int(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::Integer>(&arg_value.storage())) return *value;
    // Pythonではboolがintのサブクラスなのでisinstance(True, int)も成立する。
    if (const auto* value = std::get_if<bool>(&arg_value.storage())) return *value ? 1 : 0;
    throw std::invalid_argument("enforce_int: value is not an integer");
}

::cw::lib::Real enforce_float(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::Real>(&arg_value.storage())) {
        return *value;
    }
    throw std::invalid_argument("enforce_float: value is not a float");
}

::cw::lib::Real enforce_float_or_int(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::Real>(&arg_value.storage())) {
        return *value;
    }
    if (const auto* value = std::get_if<::cw::lib::Integer>(&arg_value.storage())) return static_cast<double>(*value);
    if (const auto* value = std::get_if<bool>(&arg_value.storage())) return *value ? 1.0 : 0.0;
    throw std::invalid_argument("enforce_float_or_int: value is not numeric");
}

bool enforce_bool(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<bool>(&arg_value.storage())) return *value;
    throw std::invalid_argument("enforce_bool: value is not a bool");
}

::cw::lib::Bytes enforce_bytes(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::Bytes>(&arg_value.storage())) return *value;
    throw std::invalid_argument("enforce_bytes: value is not bytes");
}

std::optional<::cw::lib::Bytes> enforce_optional_bytes(::cw::lib::Value arg_value)
{
    if (const auto* value = std::get_if<::cw::lib::Bytes>(&arg_value.storage())) return *value;
    bool falsy = arg_value.is_none();
    if (const auto* value = std::get_if<bool>(&arg_value.storage())) falsy = !*value;
    if (const auto* value = std::get_if<::cw::lib::Integer>(&arg_value.storage())) falsy = *value == 0;
    if (const auto* value = std::get_if<::cw::lib::Real>(&arg_value.storage())) falsy = *value == 0.0;
    if (const auto* value = std::get_if<::cw::lib::Decimal>(&arg_value.storage())) falsy = value->is_zero();
    if (const auto* value = std::get_if<::cw::lib::String>(&arg_value.storage())) falsy = value->empty();
    if (falsy) return std::nullopt;
    throw std::invalid_argument("enforce_optional_bytes: value is truthy and not bytes");
}

